import { Injectable } from "@angular/core";
import { AlertController, ToastController } from "@ionic/angular";
import { ApiService } from "./api.service";
import { TranslateService } from "@ngx-translate/core";
import { Diagnostic } from '@ionic-native/diagnostic/ngx';

@Injectable({
  providedIn: "root",
})
export class AlertService {
  public languageType: any;
  public ok: any;

  constructor(
    public alertController: AlertController,
    public apiService: ApiService,
    private _translate: TranslateService,
    public toastController: ToastController,
    private diagnostic:Diagnostic
  ) {
    this.appLanguage();
  }

  appLanguage() {
    this.apiService.languageInfo.subscribe((data: any) => {
      this.languageType = data;      
      this._translate.use(this.languageType);
      this._initialiseTranslation();
    });
  }

  _initialiseTranslation(): void {
    this._translate.get("ok").subscribe((res: string) => {
      this.ok = res;
    });
  }


  async showAlert(alertInfo = "", message = "") {
    const alert = await this.alertController.create({
      header: alertInfo,
      message: message,
      buttons: [{ text: this.ok }],
    });
    await alert.present();
  }

  async toast(message: string) {
    const toast = await this.toastController.create({
      message: message,
      duration: 2000,
      color: 'success'
    });
    toast.present();
  }

  async customtoast(message: string, time: number) {
    const toast = await this.toastController.create({
      message: message,
      duration: time
    });
    toast.present();
  }

  info(message: string) {
    this.toast(message);
  }

  custommessage(message, time) {
    this.customtoast(message, time);
  }

  warning(message: string) {
    this.toast(message);
  }

  success(message: string, keepAfterNavigationChange = false) {
    this.toast(message);
  }

  alert(message: string) {
    this.toast(message);
  }

  public async error(message: string) {
    const toast = await this.toastController.create({
      message: message,
      color: 'danger',
      duration: 2000
    });
    toast.present();
  }

  async alertWhite(message: string) {
    const alert = await this.alertController.create({
      header: 'Alert',
      message: message,
      buttons: ['OK']
    });

    await alert.present();
  }

  async alertToTurnOnPermission(headerMsg: string, message: string) {
    const alert = await this.alertController.create({
      header: `Need ${headerMsg} Permission`,
      message: `This app need to access ${message} in order to use this feature. Go to settings and turn on ${message} permission manually.`,
      buttons: [{
        text: 'Cancel',
        cssClass: 'alert-btn alert-cancel-btn',
        handler: () => {

        }
      }, {
        text: 'Go to settings',
        cssClass: 'alert-btn alert-yes-btn',
        handler: () => {
          this.diagnostic.switchToSettings();
        }
      }],
      backdropDismiss: false
    });

    await alert.present();
  }
}
